const sections = $input.first().json?.MediaContainer?.Directory || [];
const plexToken = $env.PLEX_TOKEN;
const allItems = [];

for (const section of sections) {
  const sectionId = section.key;
  const sectionType = section.type; // 'movie', 'show', 'artist'

  if (!['movie', 'show', 'artist'].includes(sectionType)) continue;

  try {
    const resp = await fetch(
      `http://localhost:32400/library/sections/${sectionId}/all?X-Plex-Token=${plexToken}`,
      { headers: { 'Accept': 'application/json' } }
    );
    const data = await resp.json();
    const items = data?.MediaContainer?.Metadata || [];

    for (const item of items) {
      let mediaType = 'Movie';
      if (sectionType === 'show') mediaType = 'TV Show';
      else if (sectionType === 'artist') mediaType = 'Music Album';

      let quality = 'SD';
      if (item.Media && item.Media[0]) {
        const height = item.Media[0].videoResolution || '';
        if (height === '4k' || height === '2160') quality = '4K';
        else if (height === '1080') quality = '1080p';
        else if (height === '720') quality = '720p';
      }

      let fileSizeMB = 0;
      if (item.Media && item.Media[0] && item.Media[0].Part && item.Media[0].Part[0]) {
        fileSizeMB = Math.round((item.Media[0].Part[0].size || 0) / 1048576);
      }

      allItems.push({
        title: item.title || 'Unknown',
        type: mediaType,
        genre: (item.Genre || []).map(g => g.tag),
        year: item.year || null,
        studio: item.studio || (item.Director ? item.Director[0]?.tag : '') || '',
        durationMin: item.duration ? Math.round(item.duration / 60000) : null,
        quality: quality,
        fileSizeMB: fileSizeMB,
        plexId: String(item.ratingKey || ''),
        addedAt: item.addedAt ? new Date(item.addedAt * 1000).toISOString().split('T')[0] : null,
        viewCount: item.viewCount || 0
      });
    }
  } catch (e) {
    // Skip failed sections
  }
}

return [{ json: { items: allItems, total: allItems.length } }];

const plexItems = $('Fetch All Plex Items').first().json.items;
const notionResults = $('Query Existing Notion Entries').first().json.results || [];

const existingPlexIds = new Map();
for (const page of notionResults) {
  const plexId = page.properties?.['Plex ID']?.rich_text?.[0]?.plain_text || '';
  if (plexId) existingPlexIds.set(plexId, page.id);
}

const toCreate = [];
const toUpdate = [];

for (const item of plexItems) {
  if (existingPlexIds.has(item.plexId)) {
    toUpdate.push({ ...item, notionPageId: existingPlexIds.get(item.plexId) });
  } else {
    toCreate.push(item);
  }
}

return [{ json: { toCreate, toUpdate, stats: { total: plexItems.length, new: toCreate.length, existing: toUpdate.length } } }];

const { toCreate, toUpdate, stats } = $input.first().json;
const notionToken = $env.NOTION_TOKEN;
const dbId = '3da63d55-66c5-8113-8c2e-d9bc95357696';
let created = 0, updated = 0, errors = 0;

for (const item of toCreate.slice(0, 50)) {
  try {
    const body = {
      parent: { database_id: dbId },
      properties: {
        'Title': { title: [{ text: { content: item.title.slice(0, 200) } }] },
        'Type': { select: { name: item.type } },
        'Genre': { multi_select: (item.genre || []).slice(0, 10).map(g => ({ name: g.slice(0, 100) })) },
        'Year': item.year ? { number: item.year } : { number: null },
        'Studio': { rich_text: [{ text: { content: (item.studio || '').slice(0, 200) } }] },
        'Duration Min': item.durationMin ? { number: item.durationMin } : { number: null },
        'Quality': { select: { name: item.quality } },
        'File Size MB': { number: item.fileSizeMB },
        'Plex ID': { rich_text: [{ text: { content: item.plexId } }] },
        'Status': { select: { name: item.viewCount > 0 ? 'Watched' : 'Unwatched' } }
      }
    };
    const resp = await fetch('https://api.notion.com/v1/pages', {
      method: 'POST',
      headers: { 'Authorization': notionToken, 'Notion-Version': '2022-06-28', 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });
    if (resp.ok) created++; else errors++;
  } catch (e) { errors++; }
}

return [{ json: { created, updated: 0, unchanged: stats.existing, errors, total: stats.total } }];

const result = $input.first().json;
console.log(`Video & Music Sync: ${result.created} created, ${result.unchanged} unchanged, ${result.errors} errors (${result.total} total Plex items)`);
return [{ json: result }];
